CREATE TABLE runner_jobs (id TEXT PRIMARY KEY, command_id TEXT NOT NULL, job_type TEXT NOT NULL, payload TEXT NOT NULL CHECK (json_valid(payload)), payload_hash TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('queued', 'claimed', 'completed', 'failed')), device_id TEXT, fencing_token INTEGER NOT NULL DEFAULT 0, expires_at TEXT, result TEXT CHECK (result IS NULL OR json_valid(result)), created_at TEXT NOT NULL, claimed_at TEXT, completed_at TEXT);
